export function compactUI(){if(!document.body.classList.contains('game-page'))return;const menu=document.createElement('button');menu.id='toolsToggle';menu.textContent='☰ Tiện ích';menu.setAttribute('aria-expanded','false');const drawer=document.createElement('aside');drawer.id='toolsDrawer';drawer.hidden=true;drawer.setAttribute('aria-label','Tiện ích trò chơi');document.body.append(menu,drawer);for(const selector of ['.world-rail','.life-nav','.game-dock','.map-zoom','#hallActions','#enterHall','#weather','#settings']){const el=document.querySelector(selector);if(el)drawer.append(el);}menu.onclick=()=>{drawer.hidden=!drawer.hidden;menu.setAttribute('aria-expanded',String(!drawer.hidden));};drawer.addEventListener('click',e=>{if(e.target.closest('button')&&!e.target.closest('.map-zoom')){drawer.hidden=true;menu.setAttribute('aria-expanded','false');}});const hint=document.querySelector('#hint');if(hint)hint.hidden=true;}
